test("Regional heading escapes HTML",{h<-region_heading_html("Custom <Region>",2);check_tables(h);stopifnot(grepl("&lt;Region&gt;",h,fixed=TRUE))})
summary<-list(passed=all(vapply(results,function(x)x$passed,logical(1))),tests=length(results),failed=sum(!vapply(results,function(x)x$passed,logical(1))),R_version=as.character(getRversion()),minimal_mode=isTRUE(getOption("unbrief.minimal")),network="Mocked only; no live API request",package_backends_tested=as.list(c("jsonlite","digest","base64enc","xml2")[vapply(c("jsonlite","digest","base64enc","xml2"),requireNamespace,logical(1),quietly=TRUE)]),results=results)
json_write("validation/r_tests.json",summary);write_text("validation/r_tests_sessionInfo.txt",capture.output(sessionInfo()));unlink(tmp,recursive=TRUE)
cat(sprintf("\n%d tests; %d failures.\n",summary$tests,summary$failed))
if(!summary$passed)quit(status=1)
